<template><section class="checkout-package-editor"><h2>Mẫu kiện khi đặt hàng</h2><p>Khai báo đúng bộ sản phẩm, số lượng và số đo toàn kiện đã đóng gói. Người mua chỉ được báo phí khi giỏ khớp một mẫu đang bật. Không suy đoán số đo từ cây hoặc dùng mẫu cho bộ hàng khác.</p><p v-if="loading" role="status">Đang tải mẫu kiện…</p><p v-if="error" role="alert">{{ error }}</p><p v-if="success" role="status">{{ success }}</p><button v-if="error" class="button button-outline" :disabled="busy" @click="load">Tải lại</button>
<form v-if="!loading && loaded" :aria-busy="busy" @submit.prevent="save"><fieldset :disabled="busy"><label for="checkout-package-select">Mẫu kiện</label><select id="checkout-package-select" v-model="selected" @change="edit"><option value="new">Thêm mẫu mới</option><option v-for="(p,i) in packages" :key="p.id" :value="p.id">Mẫu {{ i+1 }} · {{ p.enabled?'Đang bật':'Đang tắt' }}</option></select>
<div v-for="(item,i) in items" :key="i" class="package-product"><div><label :for="'package-product-'+i">Sản phẩm</label><select :id="'package-product-'+i" v-model.number="item.productId" required><option :value="null">Chọn sản phẩm</option><option v-for="p in products" :key="p.productId" :value="p.productId">{{ p.name }}</option></select></div><div><label :for="'package-quantity-'+i">Số lượng</label><input :id="'package-quantity-'+i" v-model.number="item.quantity" type="number" min="1" max="1000000" required/></div><button v-if="items.length>1" class="button button-outline" type="button" @click="items.splice(i,1)">Bỏ dòng {{ i+1 }}</button></div><button class="button button-outline" type="button" :disabled="items.length>=100" @click="items.push({productId:null,quantity:1})">Thêm sản phẩm vào kiện</button>
<div class="package-measurements"><div v-for="f in measures" :key="f.key"><label :for="'checkout-package-'+f.key">{{ f.label }}</label><input :id="'checkout-package-'+f.key" v-model.number="parcel[f.key]" type="number" min="1" :max="f.max" required/></div></div>
<label class="package-check"><input v-model="accepted" type="checkbox"/>Tôi đã xác minh với GHN rằng loại hàng, cây sống hoặc hàng dễ vỡ nếu có, và cách đóng gói này được chấp nhận. Số đo là của toàn kiện chứa đúng bộ hàng đã khai báo.</label><label class="package-check"><input v-model="enabled" type="checkbox"/>Cho phép Người mua sử dụng mẫu kiện này khi đặt hàng</label><p>Quyền thu hộ COD cần được quản trị viên xác nhận riêng cho gian hàng. Lưu mẫu không tự kích hoạt tài khoản hãng.</p><button class="button button-primary" type="submit">{{ busy?'Đang lưu…':'Lưu mẫu kiện' }}</button></fieldset></form></section></template>
<script setup>
import {onMounted,reactive,ref} from 'vue';import {marketplaceRequest as request} from '../../services/marketplace.js';
const loading=ref(true),loaded=ref(false),busy=ref(false),error=ref(''),success=ref(''),packages=ref([]),products=ref([]),selected=ref('new'),items=ref([{productId:null,quantity:1}]),parcel=reactive({weightGrams:'',lengthCm:'',widthCm:'',heightCm:''}),accepted=ref(false),enabled=ref(false);let revision=0;
const measures=[{key:'weightGrams',label:'Khối lượng cả kiện (g)',max:19999},{key:'lengthCm',label:'Dài (cm)',max:200},{key:'widthCm',label:'Rộng (cm)',max:200},{key:'heightCm',label:'Cao (cm)',max:200}];
async function load(){loading.value=true;error.value='';try{const [p,stock]=await Promise.all([request('/seller/store/checkout-packages'),request('/seller/inventory?page=0&size=50')]);packages.value=p;products.value=stock.content;loaded.value=true;}catch(e){error.value=e.message;}finally{loading.value=false;}}
function edit(){const row=packages.value.find(p=>p.id===selected.value);revision=row?.revision||0;items.value=row?JSON.parse(row.contents):[{productId:null,quantity:1}];Object.assign(parcel,row?JSON.parse(row.parcel):{weightGrams:'',lengthCm:'',widthCm:'',heightCm:''});enabled.value=!!row?.enabled;accepted.value=false;success.value='';}
async function save(){if(busy.value)return;busy.value=true;error.value='';success.value='';try{const id=selected.value==='new'?crypto.randomUUID():selected.value;await request('/seller/store/checkout-packages/'+id,'PUT',{items:items.value,parcel:{...parcel,carrierAcceptedGoods:accepted.value,revision:0},enabled:enabled.value,revision});await load();selected.value=id;edit();success.value='Đã lưu và tải lại mẫu kiện từ máy chủ.';}catch(e){error.value=e.message;}finally{busy.value=false;}}onMounted(load);
</script>
<style scoped>.checkout-package-editor{margin-top:40px;padding-top:28px;border-top:1px solid var(--bm-border);overflow-wrap:anywhere}.checkout-package-editor p{max-width:75ch;line-height:1.65}.checkout-package-editor fieldset{border:0;padding:0;min-width:0}.checkout-package-editor label{display:block;margin:16px 0 8px}.checkout-package-editor input:not([type=checkbox]),.checkout-package-editor select{font:inherit;width:100%;min-height:48px;border:1px solid var(--bm-control-border);border-radius:var(--bm-radius-control);background:var(--bm-surface);padding:10px;min-width:0;box-sizing:border-box}.package-product{display:grid;grid-template-columns:minmax(0,1fr) 100px auto;gap:16px;align-items:end;margin:20px 0}.package-measurements{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px;margin:24px 0}.package-check{display:flex!important;gap:12px;line-height:1.6}.package-check input{width:20px;height:20px;flex-shrink:0;accent-color:var(--bm-forest)}.checkout-package-editor :focus-visible{outline:3px solid var(--bm-forest);outline-offset:3px}@media(max-width:600px){.package-product{grid-template-columns:minmax(0,1fr) 80px}.package-product button{grid-column:1/-1}.package-measurements{grid-template-columns:1fr 1fr}}</style>
